create table d_trd_otc_trade(key_otc_trade_id string comment 'TRADEFLOW内部交易流水号',key_instrument_id string comment '场外合约交易流水号',business_type string comment '业务类型',key_book_id string comment '账簿ID',internal_trade_id string comment '交易内部编号',created_datetime string comment '创建时间',created_by string comment '创建人',updated_datetime string comment '修改时间',updated_by string comment '修改人',data_time string comment '数据时间') partitioned by (busi_date string comment '业务日期') row format delimited fields terminated by ',' stored as textfile;
